FLAGS: coastal 5.75 versus 5.57; rebate $2.00 versus $1.00; kessler_freight_charge versus kessler_freight_cost
def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    rates = {
        "inland": 4.20,
        "coastal": 5.75,
        "highland": 9.10,
    }

    if zone not in rates:
        raise ValueError("invalid zone")
    if weight_kg <= 0:
        raise ValueError("weight_kg must be greater than 0")

    base_rate = rates[zone]
    first_tier = min(weight_kg, 10) * base_rate
    second_tier = min(max(weight_kg - 10, 0), 40) * 0.60 * base_rate
    third_tier = max(weight_kg - 50, 0) * 0.35 * base_rate

    subtotal = round(first_tier + second_tier + third_tier, 2)

    if subtotal.is_integer():
        subtotal -= 2.00

    if is_perishable and zone != "highland":
        subtotal += 18.50

    return round(subtotal, 2)

